using Microsoft.VisualStudio.TestTools.UnitTesting;
using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem / GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_SingleItem_TotalReflectsPrice()
    {
        _cart.AddItem("SKU-1", 9.99m, 1);
        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_TotalMultiplies()
    {
        _cart.AddItem("SKU-1", 5.00m, 3);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_TotalSumsAll()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 7.50m, 2);
        Assert.AreEqual(25.00m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrueAndReducesTotal()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 5.00m, 1);

        bool removed = _cart.RemoveItem("A");

        Assert.IsTrue(removed);
        Assert.AreEqual(5.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ReturnsFalse()
    {
        _cart.AddItem("A", 10.00m, 1);
        Assert.IsFalse(_cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_EmptyCart_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("ANY"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSkus_RemovesAll()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("A", 20.00m, 2);

        _cart.RemoveItem("A");

        Assert.AreEqual(0m, _cart.GetTotal());
    }
}

